const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');

const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
const api=`https://api.github.com/repos/${repo}/contents/${path}`;
const assert=(v,m)=>{if(!v)throw new Error(m)};

async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,decl}}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;assert(out.includes(tag),`Missing core tag ${name}`);out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}
function duplicateReport(html){const p=parse(html),counts=new Map();for(const n of p.decl)counts.set(n.id.name,(counts.get(n.id.name)||0)+1);return{total:p.decl.length,dupes:[...counts.entries()].filter(([,n])=>n>1).sort((a,b)=>a[0].localeCompare(b[0]))}}
function removeEarlierDuplicates(html,spec){const p=parse(html);let code=p.code;const cuts=[];for(const[name,expected]of Object.entries(spec)){const nodes=p.decl.filter(n=>n.id.name===name).sort((a,b)=>a.start-b.start);assert(nodes.length===expected,`${name}: expected ${expected}, got ${nodes.length}`);for(const n of nodes.slice(0,-1))cuts.push([n.start,n.end,name])}for(const[start,end,name]of cuts.sort((a,b)=>b[0]-a[0])){code=code.slice(0,start)+`/* canonicalized ${name}: earlier declaration removed */`+code.slice(end)}return html.slice(0,p.start)+code+html.slice(p.sc)}

(async()=>{
 const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};console.log('Current Mobile blob '+index.sha);
 const before=duplicateReport(index.text),expected={physicalAttack:3,availableAttackersV610:2,canDeclareCombatV610:2,creatureCommandHtml:2};
 for(const[name,count]of Object.entries(expected))assert(before.dupes.some(([n,c])=>n===name&&c===count),`${name}: duplicate precondition failed`);
 const html=removeEarlierDuplicates(index.text,expected),after=duplicateReport(html);
 for(const name of Object.keys(expected))assert(!after.dupes.some(([n])=>n===name),`${name}: still duplicated`);
 assert(after.total===before.total-5,`Expected to remove 5 declarations, removed ${before.total-after.total}`);
 assert(after.dupes.length===before.dupes.length-4,`Expected duplicate-name count ${before.dupes.length-4}, got ${after.dupes.length}`);
 console.log(`Duplicate names ${before.dupes.length} -> ${after.dupes.length}; declarations ${before.total} -> ${after.total}`);

 const marker='window.SIZA={';assert(index.text.includes(marker)&&html.includes(marker),'SIZA export marker missing');
 const probe=`window.__DUP_TEST__={createMatch,setMatch:m=>state.match=m,availableAttackersV610,canDeclareCombatV610,creatureCommandHtml,physicalAttack,addCreatureV070};\n`;
 const oldDom=makeDom(inlineCore(index.text,files).replace(marker,probe+marker),'old'),newDom=makeDom(inlineCore(html,files).replace(marker,probe+marker),'new');oldDom.window.setTimeout=()=>0;newDom.window.setTimeout=()=>0;
 function snapshot(dom){const H=dom.window.__DUP_TEST__,M=H.createMatch(false,'prepare');H.setMatch(M);M.player.battlefield=[];M.player.powerCounters=[];M.player.summonedOn=[];M.player.exhausted=[];M.player.combatUsed=false;M.pendingChoice=null;H.addCreatureV070(M.player,'servitor');const preparing=H.availableAttackersV610().slice();const canPreparing=H.canDeclareCombatV610();M.player.ownTurn++;const ready=H.availableAttackersV610().slice();const canReady=H.canDeclareCombatV610();M.pendingChoice={type:'observe',cardId:'spark'};const blockedByChoice=H.canDeclareCombatV610();M.pendingChoice=null;M.ui.creature=-1;const command=H.creatureCommandHtml();const life=M.enemy.life;H.physicalAttack();return{preparing,canPreparing,ready,canReady,blockedByChoice,hasAttack:command.includes('ATACAR'),hasPhysical:command.includes('FÍSICO'),enemyLife:M.enemy.life,life}}
 const oldSnap=snapshot(oldDom),newSnap=snapshot(newDom);assert(JSON.stringify(oldSnap)===JSON.stringify(newSnap),'Combat/UI behavior changed after duplicate cleanup');assert(oldSnap.preparing.length===0&&!oldSnap.canPreparing&&oldSnap.ready[0]===0&&oldSnap.canReady&&!oldSnap.blockedByChoice&&oldSnap.hasAttack&&!oldSnap.hasPhysical&&oldSnap.enemyLife===oldSnap.life,'Canonical combat/UI contract unexpected');console.log('PASS canonical combat/UI behavior unchanged');
 const oldCore=oldDom.window.SIZA.runArenaCriticalV071(),newCore=newDom.window.SIZA.runArenaCriticalV071();assert(oldCore.passed===oldCore.total&&newCore.passed===newCore.total&&JSON.stringify(oldCore.results.map(x=>x.pass))===JSON.stringify(newCore.results.map(x=>x.pass)),'Arena critical contract changed');console.log(`PASS Arena old ${oldCore.passed}/${oldCore.total} -> new ${newCore.passed}/${newCore.total}`);oldDom.window.close();newDom.window.close();
 const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Canonicalize combat and command UI declarations',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha);
})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
